import numpy as np, glob
def parse(cif):
    cols,rows,inl=[],[],False
    for line in open(cif):
        s=line.strip()
        if s.startswith('_atom_site.'): cols.append(s.split('.')[1]); inl=True; continue
        if inl:
            if s.startswith('#') or not s:
                if rows: break
                continue
            if s.startswith('_'): break
            p=s.split()
            if len(p)>=len(cols): rows.append(p)
    i={c:n for n,c in enumerate(cols)}
    return [(p[i['label_asym_id']],int(p[i['label_seq_id']]),float(p[i['Cartn_x']]),float(p[i['Cartn_y']]),float(p[i['Cartn_z']])) for p in rows if p[i['label_seq_id']].isdigit()]
TOP={'MicroTrem2-Agonist-M1':('TREM2',18,[(19,174)]),'PfcACh-PAM-P1':('CHRNA7',22,[(23,233)])}
for code,(tgt,off,spans) in TOP.items():
    at=parse(glob.glob('/tmp/cbc_msa10/%s_native/boltz_results_input/predictions/input/input_model_0.cif'%code)[0])
    ch={}
    for c,r,x,y,z in at: ch.setdefault(c,[]).append((r,np.array([x,y,z])))
    k=sorted(ch,key=lambda a:-len(ch[a])); R,P=ch[k[0]],ch[k[1]]
    Rv=np.array([v for _,v in R]); Rr=np.array([r for r,_ in R]); Pv=np.array([v for _,v in P])
    d=np.linalg.norm(Rv[:,None]-Pv[None],axis=-1).min(1); res=sorted(set(Rr[d<5.0].tolist()))
    ext=[r for r in res if any(a<=r+off<=b for a,b in spans)]
    print('%-24s %-7s contacts=%d on_extracellular=%d (%.0f%%) canonical span %d-%d'%(code,tgt,len(res),len(ext),100*len(ext)/len(res),res[0]+off,res[-1]+off))
PY

